// ---------------------------------------------------------------------------
// WF6_solicitar_visita · Preparar las llamadas a WF5 (D33, opción A). 2026-10-15.
// Lee la respuesta de POST /visits y decide qué copiar al calendario:
//   sustituye_a                -> WF5 'borrar' la solicitud anterior (el cliente cambió de día)
//   visita en 'solicitada'     -> WF5 'guardar' como PENDIENTE (morado)
// Un 200 con la visita ya 'confirmada' no se copia: su evento ya es verde y lleva
// el nombre real; reescribirlo pondría "Solicitud del chat" en el título.
// El título no lleva el nombre: este flujo no tiene la llave de administración
// (X-Gate-Secret) y el Agente 2 nunca debe tenerla cerca. Al confirmar, el
// formulario actualiza el MISMO evento con el nombre real.
// Salida: 1 elemento por llamada a WF5, o { sin_calendario: true }.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------
const resp = $('pedir_visita').first().json;          // respuesta completa del backend
const ent = $('Al ser llamado').first().json;         // lo que mandó el agente (y n8n)
const estado = resp.statusCode;                       // 201, 200, 409, 422...
const b = resp.body ?? {};                            // el cuerpo ("?? {}": vacío si no hay)

// Sin solicitud registrada: nada que copiar.
if ((estado !== 201 && estado !== 200) || !b.visita_id) return [{ json: { sin_calendario: true } }];

// Lo común: título genérico, tipo de reforma y oportunidad (para el enlace a la ficha).
const comun = { nombre: 'Solicitud del chat', tipo_reforma: ent.tipo_reforma ?? '', oportunidad_id: ent.oportunidad_id };
const llamadas = [];                                  // en orden: primero borrar, después guardar
// 1. La solicitud anterior que el backend ha cancelado al sustituirla.
if (b.sustituye_a) {
  llamadas.push({ accion: 'borrar', visita_id: b.sustituye_a, estado_visita: '', inicio: '', fin: '', ...comun });
}
// 2. La solicitud nueva (o repetida), solo si sigue pendiente. Inicio y fin, del backend.
if (b.estado === 'solicitada') {
  llamadas.push({ accion: 'guardar', visita_id: b.visita_id, estado_visita: 'solicitada',
                  inicio: b.fecha_propuesta ?? '', fin: b.fecha_fin_visita ?? '', ...comun });
}
if (llamadas.length === 0) return [{ json: { sin_calendario: true } }];
// Un elemento por llamada: llamar_calendario (modo "each") llama a WF5 una vez por cada uno.
return llamadas.map((j) => ({ json: j }));

// ---------------------------------------------------------------------------
// WF6_solicitar_visita · Respuesta para el agente y ¿aviso técnico? 2026-10-15.
// Recibe de tres sitios (se sabe cuál con $prevNode.name):
//   pedir_visita         -> su salida de ERROR: el backend no respondió
//   necesita_calendario  -> no había nada que copiar al calendario
//   llamar_calendario    -> 1 resultado de WF5 por llamada (o { error } si WF5 no se ejecutó)
// Salida (1 elemento): { respuesta, aviso, nodo_fallo, mensaje_error }
//   respuesta: lo ÚNICO que verá el agente. Sin ids internos, sin importes y sin
//              el "input" de los 422 (podría repetir el texto con datos del cliente).
//   aviso:     true si hay que avisar al técnico (WF4). Si WF5 se ejecutó y falló,
//              ya avisó él: aquí no se avisa otra vez.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// Corregido 2026-10-15 (prueba 98): $('pedir_visita').first(0), ver abajo.
// ---------------------------------------------------------------------------
const origen = $prevNode.name;

// Texto de un error de n8n sin el objeto entero.
function textoError(e) {
  if (!e) return 'sin detalle';
  if (typeof e === 'string') return e;
  const partes = [e.code, e.message, e.description].filter((x) => typeof x === 'string' && x.trim() !== '');
  return partes.length > 0 ? partes.join(' · ') : 'error sin texto';
}

let respuesta;                 // para el agente
let aviso = false;             // ¿avisar al técnico?
let nodo_fallo = '';           // qué paso falló (para el aviso)
let mensaje_error = '';        // qué pasó (para el aviso, sin datos del cliente)

if (origen === 'pedir_visita') {
  // El backend no respondió (red, uvicorn parado...).
  respuesta = { resultado: 'no_disponible' };
  aviso = true; nodo_fallo = 'pedir_visita';
  mensaje_error = `Sin respuesta del backend en POST /visits: ${textoError($input.first().json.error)}`;
} else {
  // first(0): la salida 0 (respuesta) de pedir_visita. Sin el 0, n8n elegiría la
  // salida por la que este nodo está conectado a pedir_visita, que es la de ERROR
  // (vacía): eso rompió la prueba 98 (workflow-data-proxy.ts, n8n 2.16.1).
  const r = $('pedir_visita').first(0).json;          // la respuesta del backend
  const estado = r.statusCode;
  const b = r.body ?? {};
  const d = b.detail;                                  // los errores vienen en "detail"
  if (estado === 201 || estado === 200) {
    // Registrada. fecha_propuesta: "2026-10-23T09:45:00+02:00" -> fecha y hora de Madrid.
    const fp = String(b.fecha_propuesta ?? '');
    respuesta = { resultado: 'solicitud_registrada', estado_visita: b.estado,
                  fecha: fp.slice(0, 10), hora: fp.slice(11, 16),
                  sustituye_otra_solicitud: b.sustituye_a != null,
                  ya_estaba_registrada: b.creado === false };
  } else if (estado === 422 && Array.isArray(d)) {
    // 422 de formato (Pydantic): solo el campo y el problema, nunca el "input".
    respuesta = { resultado: 'error', motivo: 'datos_mal_formados',
                  campos: d.map((x) => ({ campo: (x.loc ?? []).slice(-1)[0] ?? '', problema: x.msg ?? '' })) };
  } else if (d && typeof d === 'object' && typeof d.motivo === 'string' && estado !== 503) {
    // Error de negocio (404, 409, 422 de fecha): motivo y mensaje del backend.
    respuesta = { resultado: 'error', motivo: d.motivo, mensaje: d.mensaje ?? '' };
    if (Array.isArray(d.huecos_libres)) respuesta.huecos_libres = d.huecos_libres;
    if (d.horas_validas) respuesta.horas_validas = d.horas_validas;
  } else {
    // 401, 500, 503 u otra respuesta: fallo técnico.
    respuesta = { resultado: 'no_disponible' };
    aviso = true; nodo_fallo = 'pedir_visita';
    mensaje_error = `POST /visits respondió ${estado}${d && d.motivo ? ` (${d.motivo})` : ''}.`;
  }

  // El calendario: solo hace falta avisar aquí si WF5 NO llegó a ejecutarse.
  if (origen === 'llamar_calendario') {
    const pedidas = $('preparar_calendario').all().map((i) => i.json);
    const res = $input.all().map((i) => i.json);
    const falloLlamada = res.length !== pedidas.length || res.some((x) => typeof x.ok !== 'boolean');
    if (falloLlamada) {
      aviso = true; nodo_fallo = 'llamar_calendario';
      mensaje_error = `WF5 no se pudo ejecutar (${res.length} de ${pedidas.length} respuestas): ` +
        res.map((x) => textoError(x.error)).join(' | ');
    }
  }
}
return [{ json: { respuesta, aviso, nodo_fallo, mensaje_error } }];

// ---------------------------------------------------------------------------
// WF6_solicitar_visita · Preparar el aviso técnico (WF4). 2026-10-15.
// RGPD: ni nombre ni texto del cliente; solo el paso, el código y la oportunidad.
// Mode: Run Once for All Items.
// ---------------------------------------------------------------------------
const r = $input.first().json;                                   // la salida de evaluar
let oportunidad_id = null;                                       // de quien nos llamó
try { oportunidad_id = $('Al ser llamado').first().json.oportunidad_id ?? null; } catch (e) { oportunidad_id = null; }
return [{ json: {
  flujo: $workflow.name,                 // este subflujo
  nodo: r.nodo_fallo,                    // el paso que ha fallado
  mensaje_error: r.mensaje_error,        // qué ha pasado
  oportunidad_id,                        // para buscar el caso
  ejecucion_id: String($execution.id),   // para buscar la ejecución
} }];

// ---------------------------------------------------------------------------
// WF6_solicitar_visita · Devolver al agente SOLO la respuesta preparada. 2026-10-15.
// La tool "Call n8n Workflow Tool" entrega al agente el JSON del primer elemento
// del último nodo (comprobado en el código de n8n 2.16.1, WorkflowToolService).
// Mode: Run Once for All Items.
// ---------------------------------------------------------------------------
return [{ json: $('evaluar').first().json.respuesta }];
